*{box-sizing:border-box} :root{font-family:'Nunito',sans-serif;color:#f5f2e7;background:#141e19;font-synthesis:none} body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 20%,#2b4539,#17221d 68%);padding:20px}.game-shell{width:min(1120px,100%);background:#202d26;border:1px solid #536456;border-radius:20px;padding:14px;box-shadow:0 28px 90px #080f0bc9, inset 0 1px #ffffff18;overflow:hidden}.topbar{height:67px;display:flex;align-items:center;padding:0 11px 11px;gap:25px}.brand{display:flex;align-items:center;gap:9px;color:#f4f0db;text-decoration:none;font-size:19px;font-weight:900;letter-spacing:-.7px}.brand-light{font-weight:600;color:#b8c5a5}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:#d9e6ae;color:#34432b;font-size:21px;box-shadow:inset 0 -3px #a5b97e}.season-card{display:flex;align-items:center;gap:8px;padding:5px 13px;border-left:1px solid #ffffff1a}.season-icon{color:#f3cb78;font-size:22px}.season-card span:last-child{display:grid;line-height:1.05}.season-card b{font-size:12px}.season-card small{font:10px 'DM Mono',monospace;color:#aab8a7;margin-top:3px}.top-stats{margin-left:auto;display:flex;align-items:center;gap:11px}.stat{display:flex;align-items:center;gap:7px;border:1px solid #ffffff17;background:#17231e;padding:8px 11px;border-radius:9px;font:12px 'DM Mono',monospace;color:#dfe4d2}.stat-icon{color:#acc48a;font-size:16px}.stat.gold .stat-icon{color:#f6cb69}.icon-button{width:34px;height:34px;border:1px solid #ffffff1d;border-radius:9px;color:#d9dfcf;background:#25342c;font-size:17px;cursor:pointer}.icon-button:hover,.journal-button:hover{background:#36493b}.game-stage{position:relative;width:100%;aspect-ratio:8/5;background:#719456;border:3px solid #121a16;border-radius:12px;overflow:hidden;box-shadow:0 5px 18px #09110dc4,inset 0 0 0 1px #ffffff27}.game-stage canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scene-vignette{pointer-events:none;position:absolute;inset:0;box-shadow:inset 0 0 80px #1020182c}.quest-card{position:absolute;top:17px;left:17px;width:227px;padding:12px 14px 13px;background:#1f3025e8;border:1px solid #d5dfbc46;border-radius:10px;box-shadow:0 4px 16px #17211750;backdrop-filter:blur(4px)}.quest-heading{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#c5d49f}.quest-heading span{color:#f2ce75;margin-right:5px;font-size:13px}.quest-card #quest-text{font-size:12px;line-height:1.4;margin-top:5px;color:#f3f0e2}.quest-progress{height:4px;background:#ffffff20;border-radius:5px;margin-top:9px;overflow:hidden}.quest-progress i{display:block;width:0;height:100%;background:#c9dc88;border-radius:5px;transition:width .25s}.weather-pill{position:absolute;right:17px;top:17px;padding:7px 11px;border-radius:20px;background:#25372ccc;border:1px solid #d4dfba48;font-size:11px;color:#ece9d8;box-shadow:0 2px 9px #1118}.weather-pill span{color:#f3cb78;margin-right:5px}.weather-pill i{display:inline-block;width:6px;height:6px;background:#a5cb87;border-radius:50%;margin:0 1px 1px 5px}.toast{position:absolute;top:68px;left:50%;transform:translate(-50%,-8px);padding:9px 16px;background:#1a2a20ed;border:1px solid #cfe0b659;border-radius:8px;color:#f3efd9;font-size:13px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap;box-shadow:0 5px 20px #0f19159c}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction-hint{position:absolute;display:none;align-items:center;gap:6px;padding:5px 8px;background:#17251fe8;border-radius:7px;border:1px solid #e8e7c566;color:#f6f1dc;font-size:11px;pointer-events:none;transform:translate(-50%,-100%)}kbd{font:10px 'DM Mono',monospace;padding:2px 5px;border:1px solid #ffffff37;border-radius:4px;background:#ffffff14;color:#e3e8d5}.modal-backdrop{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:#101b16a8;backdrop-filter:blur(3px);padding:20px}.hidden{display:none!important}.modal{position:relative;width:min(440px,100%);max-height:90%;overflow:auto;background:#f1eddb;color:#334333;border-radius:16px;padding:28px 30px 26px;box-shadow:0 18px 60px #101a14a8;border:3px solid #d7d4be}.modal:before{content:'';position:absolute;inset:6px;border:1px solid #c4c6a9;border-radius:10px;pointer-events:none}.modal-close{position:absolute;right:17px;top:13px;border:0;background:transparent;color:#52644f;font-size:25px;cursor:pointer;z-index:1}.modal-kicker{font:9px 'DM Mono',monospace;letter-spacing:1.3px;color:#81936d}.modal h2{margin:6px 0 12px;font-size:26px;letter-spacing:-.7px;color:#334333}.modal p{font-size:13px;line-height:1.6;color:#59644e;margin:8px 0 13px}.modal .note{font-size:11px;color:#819078}.modal-actions{display:grid;gap:8px;margin-top:18px}.modal-action{display:flex;justify-content:space-between;align-items:center;width:100%;border:1px solid #bbc5a7;background:#e8e9d4;color:#344438;border-radius:9px;padding:11px 13px;font:700 13px 'Nunito',sans-serif;cursor:pointer;text-align:left}.modal-action:hover{background:#dce5c5;border-color:#95aa7c;transform:translateY(-1px)}.modal-action small{font:10px 'DM Mono',monospace;color:#79866b}.item-row{display:flex;align-items:center;justify-content:space-between;padding:9px 0;border-bottom:1px solid #d7dac4;font-size:13px}.item-row span:first-child{display:flex;gap:8px;align-items:center}.bottom-bar{min-height:87px;display:flex;align-items:center;gap:20px;padding:11px 7px 0}.toolbelt{display:flex;align-items:center;gap:6px}.belt-label{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#91a08e;margin-right:5px}.tool-slot{position:relative;display:grid;grid-template-columns:26px auto;grid-template-rows:23px 15px;align-items:center;min-width:76px;height:49px;padding:4px 7px;border-radius:9px;border:1px solid #ffffff1a;background:#19261f;color:#c4cbb8;cursor:pointer}.tool-slot.selected{border-color:#d6dca3;background:#354331;box-shadow:0 0 0 1px #cbd79038,inset 0 0 13px #d5e59a12;color:#f4f0d7}.tool-number{position:absolute;top:3px;right:5px;font:8px 'DM Mono',monospace;color:#9eaa8d}.tool-emoji{grid-row:1/3;grid-column:1;font-size:20px;color:#e2d59b;text-align:center}.tool-name{grid-column:2;grid-row:2;text-align:left;font-size:9px}.tool-name b{color:#d8df9b}.energy-wrap{position:relative;flex:1;max-width:180px;margin-left:auto;padding-right:8px}.energy-label{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:.5px;color:#9ba995;margin-bottom:7px}.energy-label b{color:#d4d7b8;font-weight:400}.energy-track{height:7px;border-radius:8px;background:#111b17;border:1px solid #455545;overflow:hidden}.energy-track i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#bdcf73,#e3d17d);border-radius:8px;transition:width .2s}.energy-spark{position:absolute;right:-2px;top:18px;color:#dbd796;font-size:12px}.journal-button{height:39px;padding:0 12px;display:flex;align-items:center;gap:8px;background:#29392f;border:1px solid #ffffff1a;border-radius:9px;color:#dfe2d1;cursor:pointer;font:700 11px 'Nunito',sans-serif}.journal-button>span:first-child{font-size:16px;color:#c9d49e}.journal-button kbd{font-size:8px;margin-left:4px}.mobile-tip{display:none}.touch-controls{display:none}
@media(max-width:760px){body{padding:0;display:block;background:#18231d}.game-shell{min-height:100dvh;width:100%;border:0;border-radius:0;padding:8px;display:flex;flex-direction:column;justify-content:center}.topbar{height:52px;padding:0 4px 7px;gap:9px}.brand{font-size:15px;gap:6px}.brand-mark{height:28px;width:28px;font-size:18px;border-radius:9px}.season-card{padding:4px 7px}.season-icon{font-size:17px}.season-card b{font-size:10px}.season-card small{font-size:8px}.top-stats{gap:5px}.stat{padding:6px 7px;font-size:10px;gap:4px}.stat-icon{font-size:13px}.icon-button{width:28px;height:28px;font-size:14px}.game-stage{aspect-ratio:8/5;min-height:0;border-width:2px;border-radius:8px}.quest-card{top:8px;left:8px;padding:7px 9px;width:170px;border-radius:7px}.quest-heading{font-size:7px;letter-spacing:.7px}.quest-heading span{font-size:10px}.quest-card #quest-text{font-size:9px;margin-top:3px}.quest-progress{margin-top:5px;height:3px}.weather-pill{top:8px;right:8px;padding:4px 7px;font-size:8px}.toast{top:51px;font-size:11px;padding:7px 12px}.bottom-bar{min-height:73px;padding:7px 2px 0;gap:8px;flex-wrap:wrap}.belt-label{display:none}.toolbelt{gap:4px}.tool-slot{min-width:57px;height:43px;grid-template-columns:20px auto;padding:3px 4px}.tool-emoji{font-size:16px}.tool-name{font-size:8px}.energy-wrap{max-width:none;min-width:82px;padding-right:4px}.energy-label{font-size:7px}.energy-label b{font-size:7px}.journal-button{height:34px;padding:0 8px;gap:5px;font-size:9px}.journal-button kbd{display:none}.mobile-tip{display:block;text-align:center;font-size:9px;color:#8f9b89;padding-top:5px}.touch-controls{display:flex;position:absolute;inset:auto 10px 10px;justify-content:space-between;align-items:end;pointer-events:none}.dpad{width:95px;height:88px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:2px;pointer-events:auto}.dpad button,.touch-action{border:1px solid #e7e6c45c;background:#1a2a20b8;color:#f1edda;border-radius:8px;font-size:11px;touch-action:none;user-select:none;backdrop-filter:blur(3px)}.dpad button:nth-child(1){grid-column:2;grid-row:1}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.touch-action{pointer-events:auto;width:58px;height:45px;border-radius:50%;font:9px 'DM Mono',monospace;background:#d6d89cbd;color:#243426;border-color:#f1edca;margin:0 4px 9px 0}.interaction-hint{display:none!important}.modal{padding:24px 23px}.modal h2{font-size:23px}}
@media(max-width:390px){.brand{font-size:13px}.season-card{display:none}.tool-slot{min-width:51px}.energy-wrap{min-width:70px}.journal-button{padding:0 6px}.quest-card{width:155px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 600, TILE = 32, COLS = 30, ROWS = 18;
  const ui = {
    season: document.getElementById('season'), day: document.getElementById('day-label'), clock: document.getElementById('clock'), gold: document.getElementById('gold'),
    seeds: document.getElementById('seed-count'), energy: document.getElementById('energy-value'), energyBar: document.getElementById('energy-bar'), quest: document.getElementById('quest-text'), questBar: document.getElementById('quest-bar'),
    toast: document.getElementById('toast'), modal: document.getElementById('modal'), backdrop: document.getElementById('modal-backdrop'), title: document.getElementById('modal-title'), content: document.getElementById('modal-content'), hint: document.getElementById('interaction-hint')
  };
  const state = { day:1, season:0, minutes:360, gold:120, energy:100, maxEnergy:100, seeds:8, tool:'hoe', player:{x:481,y:411,dir:'down',walk:0}, tilled:new Map(), crops:new Map(), watered:new Set(), rocks:new Set(), weeds:new Set(), inventory:{turnip:0,wood:0,stone:0}, quest:{till:false,plant:false,water:false,harvest:false}, keys:{}, pressed:new Set(), toastTimer:0, sound:false, modal:null };
  const seasons=['Spring','Summer','Autumn','Winter'];
  const tileKey=(x,y)=>`${x},${y}`;
  const tileAt=(x,y)=>({x:Math.floor(x/TILE),y:Math.floor(y/TILE)});
  const seeded=(x,y)=>{let n=(x*374761393+y*668265263)|0;n=(n^(n>>>13))*1274126177;return ((n^(n>>>16))>>>0)/4294967295};
  const obstacles=[];
  const rect=(x,y,w,h)=>({x,y,w,h});
  // Farmhouse and yard boundaries
  obstacles.push(rect(387,124,187,115),rect(362,235,16,96),rect(579,234,16,96));
  // Decorative trees outside the walkable farm paths
  const trees=[ [77,78],[146,75],[225,90],[698,81],[771,79],[859,92],[905,150],[80,512],[178,526],[769,516],[867,520],[924,464],[672,510],[286,83],[744,169],[112,424],[893,335] ];
  const rocks=[[242,459],[276,474],[292,443],[627,505],[647,474],[707,477],[327,524],[335,496]];
  const weedSpots=[[214,371],[242,395],[302,350],[325,426],[638,363],[675,397],[726,372],[312,287],[641,290],[184,315],[803,434],[553,498],[220,499],[749,299]];
  rocks.forEach(([x,y])=>obstacles.push(rect(x,y,23,20)));
  trees.forEach(([x,y])=>obstacles.push(rect(x+8,y+18,24,28)));
  const npcs=[{id:'mara',name:'Mara',x:657,y:270,shirt:'#c77962',hair:'#503c31',role:'neighbor'},{id:'pippin',name:'Pippin',x:276,y:268,shirt:'#6887a0',hair:'#a77b46',role:'shop'}];
  const keys={w:'up',ArrowUp:'up',s:'down',ArrowDown:'down',a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right'};
  function rnd(x,y){return seeded(x,y)}
  function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');state.toastTimer=2.1}
  function setQuest(){
    const q=state.quest; let done=(q.till?1:0)+(q.plant?1:0)+(q.water?1:0)+(q.harvest?1:0); ui.questBar.style.width=`${done/4*100}%`;
    if(!q.till)ui.quest.textContent='Use your hoe on a grassy patch to make a little garden.';
    else if(!q.plant)ui.quest.textContent='Plant a turnip seed in your freshly tilled soil.';
    else if(!q.water)ui.quest.textContent='Give your new seed a drink with the watering can.';
    else if(!q.harvest)ui.quest.textContent='Come back after a few mornings to harvest your turnip.';
    else ui.quest.textContent='A lovely first harvest! Grow crops and sell them in town.';
  }
  function updateHud(){ui.season.textContent=seasons[state.season];ui.day.textContent=`Day ${state.day}`;let hr=Math.floor(state.minutes/60)%24,min=state.minutes%60;ui.clock.textContent=`${hr%12||12}:${String(min).padStart(2,'0')} ${hr>=12?'PM':'AM'}`;ui.gold.textContent=state.gold;ui.seeds.textContent=state.seeds;ui.energy.textContent=`${Math.ceil(state.energy)} / ${state.maxEnergy}`;ui.energyBar.style.width=`${Math.max(0,state.energy)}%`;setQuest()}
  function spend(amount){if(state.energy<amount){showToast('You are worn out. Take a little rest.');return false}state.energy-=amount;updateHud();return true}
  function blocked(x,y){if(x<20||y<28||x>W-20||y>H-25)return true;for(const o of obstacles)if(x>o.x-13&&x<o.x+o.w+13&&y>o.y-14&&y<o.y+o.h+12)return true;for(const n of npcs)if(Math.abs(x-n.x)<21&&Math.abs(y-n.y)<23)return true;return false}
  function nearTile(){const p=state.player,dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]},d=dirs[p.dir],x=Math.floor((p.x+d[0]*25)/TILE),y=Math.floor((p.y+d[1]*25)/TILE);return {x,y,key:tileKey(x,y),cx:x*TILE+TILE/2,cy:y*TILE+TILE/2}}
  function useTool(){if(state.modal)return;const t=nearTile(),p=state.player;
    if(state.tool==='hoe'){
      if(state.tilled.has(t.key)){showToast('This patch is already turned.');return}if(!spend(4))return;state.tilled.set(t.key,true);state.quest.till=true;showToast('The soil is soft and ready.');
    } else if(state.tool==='seed'){
      if(!state.tilled.has(t.key)){showToast('Turn the earth with your hoe first.');return}if(state.crops.has(t.key)){showToast('Something is already growing here.');return}if(state.seeds<1){showToast('You are out of seeds. Visit Pippin in town.');return}if(!spend(2))return;state.seeds--;state.crops.set(t.key,{age:0,watered:false});state.quest.plant=true;showToast('A tiny turnip seed is tucked in.');
    } else if(state.tool==='water'){
      if(!state.crops.has(t.key)){showToast('Water works best on a planted seed.');return}if(state.watered.has(t.key)){showToast('That little plant has had a drink today.');return}if(!spend(1))return;state.watered.add(t.key);state.crops.get(t.key).watered=true;state.quest.water=true;showToast('A refreshing drink for your crop.');
    } else if(state.tool==='harvest'){
      const crop=state.crops.get(t.key);if(!crop){showToast('Nothing to harvest right here.');return}if(crop.age<3){showToast(`Not quite ready — ${3-crop.age} more ${3-crop.age===1?'morning':'mornings'}.`);return}state.crops.delete(t.key);state.tilled.delete(t.key);state.watered.delete(t.key);state.inventory.turnip++;state.quest.harvest=true;state.energy=Math.min(100,state.energy+3);showToast('A beautiful turnip! Take it to Pippin to sell.');
    }
    updateHud();
  }
  function interact(){if(state.modal){closeModal();return}const p=state.player,near=npcs.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<62);if(near){near.role==='shop'?openShop():openMara();return}const dist=Math.hypot(p.x-478,p.y-283);if(dist<76){openHouse();return}const bed=Math.hypot(p.x-475,p.y-201);if(bed<105){nextDay();return}showToast('Nothing to interact with nearby. Try the farmhouse or say hello in town.')}
  function openModal(title,html){ui.title.textContent=title;ui.content.innerHTML=html;ui.backdrop.classList.remove('hidden');state.modal=true}
  function closeModal(){ui.backdrop.classList.add('hidden');state.modal=null}
  function openMara(){openModal('A friendly hello',`<p>“Good morning, farmer! The valley feels extra peaceful this time of year. I saw little footprints by the river — the rabbits are waking up.”</p><p>“Pippin's stall is just across the bridge. They always have something useful for new gardeners.”</p><p class="note">Mara smiles and waves. Somehow, the morning feels brighter.</p><div class="modal-actions"><button class="modal-action" data-action="close">That's lovely <small>↵ CLOSE</small></button></div>`)}
  function openHouse(){openModal('Your cozy farmhouse',`<p>A sunbeam spills across your little cottage. This is your place to rest, plan, and watch the seasons drift by.</p><div class="item-row"><span>🌱 Turnip seeds</span><b>${state.seeds}</b></div><div class="item-row"><span>🥬 Fresh turnips</span><b>${state.inventory.turnip}</b></div><div class="item-row"><span>🪵 Wood gathered</span><b>${state.inventory.wood}</b></div><div class="modal-actions"><button class="modal-action" data-action="sleep">Sleep until morning <small>REST & SAVE</small></button><button class="modal-action" data-action="journal">Read your journal <small>J</small></button></div>`)}
  function openShop(){openModal('Pippin’s little stall',`<p>“Hey there! Fresh seeds, good prices. What sounds nice for your patch?”</p><div class="item-row"><span>🌱 Turnip seeds <small>(plant & grow)</small></span><b>8g</b></div><div class="item-row"><span>🥬 Sell turnips <small>(from your harvest)</small></span><b>25g</b></div><div class="item-row"><span>🪵 Sell wood <small>(gathered from stumps)</small></span><b>4g</b></div><div class="modal-actions"><button class="modal-action" data-action="buy-seed">Buy 5 turnip seeds <small>40g</small></button><button class="modal-action" data-action="buy-seed-one">Buy 1 turnip seed <small>8g</small></button><button class="modal-action" data-action="sell-turnips">Sell all turnips <small>${state.inventory.turnip*25}g</small></button><button class="modal-action" data-action="sell-wood">Sell all wood <small>${state.inventory.wood*4}g</small></button></div><p class="note">Pippin's stall is stocked every morning. Come back anytime!</p>`)}
  function openJournal(){openModal('Field journal',`<p>Your little guide to a happy farm.</p><div class="item-row"><span>☀ Day & season</span><b>${seasons[state.season]} ${state.day}</b></div><div class="item-row"><span>🌱 Seeds in your pocket</span><b>${state.seeds}</b></div><div class="item-row"><span>🥬 Turnips harvested</span><b>${state.inventory.turnip}</b></div><div class="item-row"><span>✦ Today's plan</span><b>${(Object.values(state.quest).filter(Boolean).length)}/4</b></div><p>Choose a tool with <b>1–4</b>, then press <b>Space</b> or click the farm to use it. Crops need water each day and grow over three mornings. Visit Pippin by the bridge to buy seeds or sell your harvest.</p><p class="note">Move with WASD or the arrow keys · E to interact · J for this journal · Walk to your bed to sleep.</p><div class="modal-actions"><button class="modal-action" data-action="close">Back to the farm <small>↵ CLOSE</small></button></div>`)}
  function nextDay(){
    closeModal();state.day++;if(state.day>28){state.day=1;state.season=(state.season+1)%4;showToast(`A new season begins: ${seasons[state.season]}!`)}else showToast('A new day in Meadowmere. You feel rested.');
    state.minutes=360;state.energy=100;state.watered.clear();state.quest={till:false,plant:false,water:false,harvest:false};
    for(const [key,crop] of state.crops){if(crop.watered)crop.age++;crop.watered=false}
    state.player.x=480;state.player.y=390;updateHud();
  }
  function action(e){const btn=e.target.closest('[data-action]');if(!btn)return;const act=btn.dataset.action;
    if(act==='close'){closeModal();return}if(act==='journal'){openJournal();return}if(act==='sleep'){nextDay();return}
    if(act==='buy-seed'||act==='buy-seed-one'){const n=act==='buy-seed'?5:1,cost=n*8;if(state.gold<cost){showToast('Not quite enough gold for that.');return}state.gold-=cost;state.seeds+=n;updateHud();openShop();showToast(`${n} ${n===1?'seed':'seeds'} tucked into your bag.`);return}
    if(act==='sell-turnips'){const n=state.inventory.turnip;if(!n){showToast('No turnips to sell just yet.');return}state.inventory.turnip=0;state.gold+=n*25;updateHud();openShop();showToast(`Sold ${n} turnip${n>1?'s':''} for ${n*25}g!`);return}
    if(act==='sell-wood'){const n=state.inventory.wood;if(!n){showToast('Gather wood from the little stumps around the farm.');return}state.inventory.wood=0;state.gold+=n*4;updateHud();openShop();showToast(`Sold your wood for ${n*4}g!`)}
  }

function drawGround(){
  const palette=state.season===0?['#789857','#759553','#7c9b5b','#739250']:state.season===1?['#85a153','#809d50','#8aa85a','#7f9a4f']:state.season===2?['#9b9558','#979052','#a29a5d','#928c50']:['#8eaa9b','#91aea0','#88a598','#95b2a3'];
