  // worn walking path
  ctx.fillStyle='#b9aa7750';ctx.beginPath();ctx.moveTo(420,232);ctx.lineTo(530,232);ctx.lineTo(560,293);ctx.lineTo(549,381);ctx.lineTo(600,415);ctx.lineTo(590,448);ctx.lineTo(503,407);ctx.lineTo(498,307);ctx.closePath();ctx.fill();
  // pond and stream
  ctx.fillStyle='#4f987e';ctx.beginPath();ctx.ellipse(850,281,73,112,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#72b5a0';ctx.beginPath();ctx.ellipse(846,274,61,97,-.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c0d0a377';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(843,270,53,88,-.2,-2.3,.7);ctx.stroke();
  ctx.fillStyle='#d5cc9c';ctx.beginPath();ctx.moveTo(516,254);ctx.lineTo(589,254);ctx.lineTo(594,279);ctx.lineTo(520,279);ctx.closePath();ctx.fill();ctx.fillStyle='#8c7655';for(let i=0;i<5;i++)ctx.fillRect(521+i*15,258,5,16);ctx.fillRect(518,258,76,4);
  // farm plot
