  for(let y=0;y<4;y++)for(let x=0;x<6;x++){let px=365+x*39,py=350+y*34;ctx.fillStyle='#a68a5c';ctx.fillRect(px,py,35,29);ctx.fillStyle='#886c47';ctx.fillRect(px+1,py+26,33,3);ctx.fillStyle='#c0a47555';ctx.fillRect(px+3,py+4,29,2)}
}
function drawHouse(){
  // drop shadow
  ctx.fillStyle='#263a2d4d';ctx.fillRect(380,208,206,36);
  // cottage side walls
  ctx.fillStyle='#d9c89b';ctx.fillRect(398,164,168,75);ctx.fillStyle='#bb9e72';ctx.fillRect(398,220,168,19);ctx.fillStyle='#e7d9b2';ctx.fillRect(406,169,152,52);
