  // roof tiles
  ctx.strokeStyle='#744b43';ctx.lineWidth=2;for(let row=0;row<4;row++){const yy=125+row*11;ctx.beginPath();ctx.moveTo(420-row*11,yy+22);ctx.lineTo(480,yy-17);ctx.lineTo(540+row*11,yy+22);ctx.stroke()}
  // chimney
