  // windows and door
  ctx.fillStyle='#72503f';ctx.fillRect(414,180,30,36);ctx.fillRect(517,180,30,36);ctx.fillStyle='#a8d0bc';ctx.fillRect(418,184,22,28);ctx.fillRect(521,184,22,28);ctx.fillStyle='#f0d992';ctx.fillRect(428,184,3,28);ctx.fillRect(418,196,22,3);ctx.fillRect(531,184,3,28);ctx.fillRect(521,196,22,3);
  ctx.fillStyle='#76513d';ctx.fillRect(463,184,34,55);ctx.fillStyle='#9a6d4d';ctx.fillRect(467,188,26,47);ctx.fillStyle='#d6b46f';ctx.fillRect(486,210,4,4);ctx.fillRect(455,235,50,5);ctx.fillStyle='#dbc99e';ctx.fillRect(463,182,34,4);
  ctx.fillStyle='#e8dfbc';ctx.font='bold 10px Nunito';ctx.textAlign='center';ctx.fillText('HOME',480,159);ctx.textAlign='left';
