function drawTree(x,y,variant=0){
  const canopy=state.season===0?['#446d46','#517a4d','#5f8552']:state.season===1?['#537745','#5d8045','#68874b']:state.season===2?['#b46e3e','#cb8041','#d0944d']:['#52766a','#668a7a','#719489'];
  ctx.fillStyle='#574637';ctx.fillRect(x+15,y+25,12,30);ctx.fillStyle='#76583c';ctx.fillRect(x+17,y+27,4,23);
  for(let i=0;i<3;i++){ctx.fillStyle=canopy[(variant+i)%3];ctx.beginPath();ctx.ellipse(x+19+(i-1)*12,y+17-(i===1?8:0),21,19,0,0,Math.PI*2);ctx.fill()}
