function drawNpc(n){
  const t=performance.now()/800, bob=Math.sin(t+n.x)*1.3;ctx.fillStyle='#283c2b55';ctx.beginPath();ctx.ellipse(n.x,n.y+12,13,5,0,0,Math.PI*2);ctx.fill();
