function drawCrop(key,crop){const [tx,ty]=key.split(',').map(Number),x=tx*TILE+16,y=ty*TILE+16;ctx.fillStyle='#644c35';ctx.fillRect(tx*TILE+2,ty*TILE+4,28,24);ctx.fillStyle='#826545';ctx.fillRect(tx*TILE+3,ty*TILE+5,26,19);
  if(crop.age===0){ctx.fillStyle='#b99a61';ctx.fillRect(x-2,y+2,4,3)}else if(crop.age===1){ctx.fillStyle='#6b9c50';ctx.fillRect(x-2,y-2,4,7);ctx.fillRect(x-7,y-1,6,3);ctx.fillRect(x+2,y-3,6,3)}else if(crop.age===2){ctx.fillStyle='#528447';ctx.fillRect(x-2,y-7,4,13);ctx.fillRect(x-9,y-4,9,4);ctx.fillRect(x+1,y-7,9,4);ctx.fillRect(x-7,y-11,6,4);ctx.fillRect(x+2,y-13,6,5)}else{ctx.fillStyle='#3f783e';ctx.fillRect(x-3,y-9,6,15);ctx.fillRect(x-11,y-6,9,5);ctx.fillRect(x+2,y-9,10,5);ctx.fillRect(x-8,y-13,7,5);ctx.fillRect(x+2,y-16,7,6);ctx.fillStyle='#f1edcf';ctx.beginPath();ctx.arc(x,y+3,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#be5661';ctx.fillRect(x-3,y,6,5);ctx.fillRect(x-5,y+2,10,3);ctx.fillStyle='#ece6c6';ctx.fillRect(x-1,y+1,2,5)}
  if(crop.watered){ctx.fillStyle='#87c8d6';ctx.fillRect(x-2,y+7,5,2)}if(crop.age>=3){ctx.fillStyle='#fff3b8';ctx.fillText('✦',x-3,y-19)}
}
function draw(){ctx.clearRect(0,0,W,H);drawGround();
  // scattered grass tufts and flowers
  for(let i=0;i<160;i++){let x=(i*173+37)%W,y=(i*97+53)%H;if((x>345&&x<612&&y>330&&y<500)||(x>360&&x<600&&y<250))continue;let r=rnd(i,71);ctx.fillStyle=r>.83?'#e7dca0':r>.65?'#d9b58e':'#547849';ctx.fillRect(x,y,2,3);if(r>.9){ctx.fillStyle='#f1e9c9';ctx.fillRect(x+2,y-2,3,3)}}
  drawHouse();for(const [x,y] of rocks){ctx.fillStyle='#6e7969';ctx.beginPath();ctx.ellipse(x+10,y+9,13,10,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a7aa8e';ctx.fillRect(x+4,y+3,9,3);ctx.fillStyle='#545f54';ctx.fillRect(x+2,y+14,17,3)}
  for(const [x,y] of weedSpots){if(state.weeds.has(`${x},${y}`))continue;ctx.fillStyle='#4a7345';ctx.fillRect(x,y,3,10);ctx.fillRect(x-4,y+2,6,3);ctx.fillRect(x+2,y-2,6,3);ctx.fillStyle='#799554';ctx.fillRect(x-3,y+7,8,2)}
  for(const [key,crop] of state.crops)drawCrop(key,crop);
  for(const [x,y] of trees)drawTree(x,y,Math.floor(rnd(x,y)*3));
  // stumps to gather wood
  for(const [x,y] of [[131,342],[817,217],[697,442]]){ctx.fillStyle='#6b4d37';ctx.fillRect(x,y,18,12);ctx.fillStyle='#b78c5c';ctx.beginPath();ctx.ellipse(x+9,y,9,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e0bb7b';ctx.beginPath();ctx.ellipse(x+9,y,4,2,0,0,Math.PI*2);ctx.fill()}
  npcs.forEach(drawNpc);
  // player shadow and sprite
  const p=state.player,bob=Math.sin(p.walk)*1.4;ctx.fillStyle='#1f392b61';ctx.beginPath();ctx.ellipse(p.x,p.y+9,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#38556b';ctx.fillRect(p.x-9,p.y-2+bob,18,17);ctx.fillStyle='#8cae9a';ctx.fillRect(p.x-7,p.y+2+bob,14,5);ctx.fillStyle='#eac49b';ctx.fillRect(p.x-7,p.y-13+bob,14,13);ctx.fillStyle='#694735';ctx.fillRect(p.x-8,p.y-17+bob,16,7);ctx.fillRect(p.x-9,p.y-14+bob,4,7);ctx.fillStyle='#453a31';ctx.fillRect(p.x-4,p.y-8+bob,2,2);ctx.fillRect(p.x+3,p.y-8+bob,2,2);ctx.fillStyle='#ead4ac';ctx.fillRect(p.x-7,p.y+14,5,5);ctx.fillRect(p.x+2,p.y+14,5,5);
  // nearby target outline
