}
function update(dt){let dx=0,dy=0;if(state.keys.up)dy--;if(state.keys.down)dy++;if(state.keys.left)dx--;if(state.keys.right)dx++;if(dx||dy){let len=Math.hypot(dx,dy);dx/=len;dy/=len;const speed=112*dt,nx=state.player.x+dx*speed,ny=state.player.y+dy*speed;if(!blocked(nx,state.player.y))state.player.x=nx;if(!blocked(state.player.x,ny))state.player.y=ny;state.player.dir=Math.abs(dx)>Math.abs(dy)?(dx<0?'left':'right'):(dy<0?'up':'down');state.player.walk+=dt*13;state.minutes=Math.min(1439,state.minutes+dt*1.1);updateHud()}
  for(const n of npcs){if(Math.hypot(n.x-state.player.x,n.y-state.player.y)<64){ui.hint.style.display='flex';ui.hint.style.left=`${n.x/W*100}%`;ui.hint.style.top=`${n.y/H*100}%`;return}}ui.hint.style.display='none';
}
let last=performance.now();function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)ui.toast.classList.remove('show')}update(dt);draw();requestAnimationFrame(loop)}

  document.addEventListener('keydown',e=>{
