  window.addEventListener('blur',()=>{state.keys={up:false,down:false,left:false,right:false}});
  function selectTool(tool){state.tool=tool;document.querySelectorAll('.tool-slot').forEach(b=>b.classList.toggle('selected',b.dataset.tool===tool));showToast(`${tool[0].toUpperCase()+tool.slice(1)} selected`)}
  document.querySelectorAll('.tool-slot').forEach(b=>b.addEventListener('click',()=>selectTool(b.dataset.tool)));
