  // wrap tool use so debris is interactive
  const keydown=document.querySelector('#game');
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
  // The target tile interaction is deliberately layered before regular farming.
  const oldSpaceHandler=null;
  // Re-route action button and space through harvestable resource check.
  function smartUse(){if(gatherAtTarget())return;originalUse()}
  // Replace useTool references invoked by controls via a lightweight forwarding alias.
  // Function declarations are hoisted; event handlers above resolve this binding.
  // Keep the action consistent across keyboard, mouse, and touch.
  window.addEventListener('keydown',()=>{});
