  document.addEventListener('keydown',e=>{if(e.key===' '&&state.tool==='harvest'){e.stopImmediatePropagation();smartUse()}},{capture:true});
  document.getElementById('touch-action').removeEventListener('pointerdown',()=>{});
  document.getElementById('touch-action').addEventListener('click',()=>{if(state.tool==='harvest')smartUse()});
  updateHud();requestAnimationFrame(loop);
})();

